SELECT
    w.main_status AS mainStatus,
    COUNT(1) AS countNum
FROM work_order w
LEFT JOIN work_order_participant p
    ON p.work_order_id = w.id
    AND p.company_id = #{query.accessContext.currentCompanyId}




                AND EXISTS (
                    SELECT 1
                    FROM work_order_flow tf
                    WHERE tf.work_order_id = w.id
                      AND tf.action_type = 'TRANSFER'
                      AND tf.from_company_id = #{query.accessContext.currentCompanyId}
                )

                    AND w.hq_company_id = #{query.accessContext.currentCompanyId}




                            AND 


                            AND 1 = 0






                            AND (
                                EXISTS (
                                    SELECT 1
                                    FROM work_order_flow tfu
                                    WHERE tfu.work_order_id = w.id
                                      AND tfu.action_type = 'TRANSFER'
                                      AND tfu.from_company_id = #{query.accessContext.currentCompanyId}
                                      AND tfu.operator_user_id = #{query.accessContext.currentUserId}
                                )
                                OR 
                            )


                            AND 1 = 0







                        AND w.hq_company_id = #{query.accessContext.currentCompanyId}
                        AND w.current_accept_company_id <> #{query.accessContext.currentCompanyId}
                        AND p.company_id = #{query.accessContext.currentCompanyId}
                        AND p.is_current_handler = 0



                                    AND 


                                    AND 1 = 0







                                        AND 


                                        AND 1 = 0








                        AND p.company_id = #{query.accessContext.currentCompanyId}
                        AND p.is_current_handler = 0



                                    AND 


                                    AND 1 = 0













                                        AND w.hq_company_id = #{query.accessContext.currentCompanyId}
                                        AND 


                                        AND 1 = 0




                                AND (
                                    w.hq_company_id = #{query.accessContext.currentCompanyId}
                                    AND (
                                    w.current_accept_company_id = #{query.accessContext.currentCompanyId}
                                    OR p.company_id = #{query.accessContext.currentCompanyId}
                                    )
                                )




                        AND (
                            w.current_accept_company_id = #{query.accessContext.currentCompanyId}
                            OR p.company_id = #{query.accessContext.currentCompanyId}

                                OR w.current_accept_company_id IN

                                    #{companyId}

                                OR EXISTS (
                                    SELECT 1
                                    FROM work_order_participant sp
                                    WHERE sp.work_order_id = w.id
                                      AND sp.company_id IN

                                          #{companyId}

                                )

                        )




                AND w.current_accept_company_id = #{query.accessContext.currentCompanyId}



                            AND w.hq_company_id = #{query.accessContext.currentCompanyId}
                            AND 


                            AND 1 = 0















        AND w.customer_name LIKE CONCAT('%', #{query.customerName}, '%')


        AND w.customer_mobile LIKE CONCAT('%', #{query.customerMobile}, '%')


        AND w.barcode LIKE CONCAT('%', #{query.barcode}, '%')


        AND w.product_model LIKE CONCAT('%', #{query.productModel}, '%')





        AND w.has_transfer = #{query.hasTransfer}




                AND 


                AND w.assigned_user_id = #{query.accessContext.currentUserId}




GROUP BY w.main_status
